// v11: mesmos filtros do workflow simples (só evento 'message', sem fromMe, sem grupo)
// + comando '#bot <numero>' enviado pelo atendente para reativar a IA de um cliente.
const ATTENDANT_PHONE = '5548999999999'; // <<< TROQUE pelo número do atendente (só dígitos, com 55 + DDD)

const raw = $input.first().json;
const body = raw.body || raw;
const event = body.event || '';
const payload = body.payload || {};
const from = String(payload.from || '');
const messageText = String(payload.body || '').trim();
const session = body.session || 'default';

const isFromMe = payload.fromMe === true;
const isGroup = from.endsWith('@g.us');
const isBroadcast = from.includes('broadcast') || from.endsWith('@newsletter');
const isMedia = payload.hasMedia === true;

// Ignora acks, status, mensagens do próprio número, grupos e mensagens vazias
if (event !== 'message' || !from || isFromMe || isGroup || isBroadcast || (!messageText && !isMedia)) {
  return [{ json: { skip: true } }];
}

const cleanPhone = from.split('@')[0];
const isAttendant = cleanPhone === ATTENDANT_PHONE.replace(/\D/g, '');

// '#bot' (cliente reativa a própria conversa) ou '#bot 5548...' (atendente reativa um cliente)
const cmd = messageText.match(/^[#\/](?:bot|ativar)(?:\s+(\S+))?$/i);
let isReactivation = false;
let reactivateTarget = null;
if (cmd && !isMedia) {
  if (cmd[1] && isAttendant) {
    isReactivation = true;
    reactivateTarget = cmd[1].split('@')[0].replace(/\D/g, '');
  } else if (!cmd[1]) {
    isReactivation = true;
    reactivateTarget = cleanPhone;
  }
}

const greetingRegex = /^(oi|ol[aá]|boa tarde|bom dia|boa noite|hey|hello|tudo bem|tudo bom|e a[ií]|oie|oii)[\s!?.]*$/i;
const isGreeting = greetingRegex.test(messageText) && !isMedia;
const criticalRegex = /(atendente|humano|pessoa|rescis[aã]o|procon|jur[ií]dico|advogado|processo|justi[çc]a|reclama[çc][aã]o|cancel|distrato|falar com algu[eé]m|quero falar)/i;
const isCritical = criticalRegex.test(messageText) && !isMedia;

return [{ json: { skip: false, from, phone: cleanPhone, message: messageText, session, isReactivation, reactivateTarget, isAttendant, isGreeting, isCritical, isMedia, timestamp: new Date().toISOString() } }];

const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.humanHandoff) staticData.humanHandoff = {};
const target = data.reactivateTarget;
const session = data.session;
const welcome = '✅ Olá! Estou de volta para te ajudar com informações sobre os empreendimentos LongView. Como posso te auxiliar?';

// Remove o modo humano de qualquer chatId desse número (@c.us ou @lid)
let clientChatId = null;
for (const key of Object.keys(staticData.humanHandoff)) {
  if (key.split('@')[0] === target) {
    clientChatId = key;
    delete staticData.humanHandoff[key];
  }
}

// O próprio cliente mandou #bot
if (target === data.phone) {
  return [{ json: { to: data.from, session, responseText: welcome } }];
}

// O atendente mandou '#bot <numero>'
const out = [];
if (clientChatId) out.push({ json: { to: clientChatId, session, responseText: welcome } });
out.push({ json: { to: data.from, session, responseText: clientChatId
  ? `✅ IA reativada para o cliente ${target}.`
  : `⚠️ Não encontrei o cliente ${target} em atendimento humano (talvez já tenha expirado).` } });
return out;

const from = $input.first().json.from;
const staticData = $getWorkflowStaticData('global');
if (!staticData.humanHandoff) staticData.humanHandoff = {};
const handoffEntry = staticData.humanHandoff[from];
let isInHumanMode = false;
if (handoffEntry) {
  const elapsed = Date.now() - new Date(handoffEntry.since).getTime();
  if (elapsed < 8 * 60 * 60 * 1000) {
    isInHumanMode = true;
  } else {
    delete staticData.humanHandoff[from];
  }
}
return [{ json: { ...$input.first().json, isInHumanMode } }];

const from = $input.first().json.from;
const session = $input.first().json.session;
return [{ json: { to: from, session, responseText: 'Desculpe, ainda não consigo ouvir áudios ou visualizar imagens. 😅\n\nPor favor, digite sua dúvida em texto para que eu possa te ajudar!' } }];

const from = $input.first().json.from;
const session = $input.first().json.session;
// O servidor (Docker) roda em UTC -- pega a hora de Brasília explicitamente
const hour = parseInt(new Date().toLocaleString('en-US', { hour: 'numeric', hour12: false, timeZone: 'America/Sao_Paulo' }), 10) % 24;
const corpo = 'Bem-vindo à LongView 🏢\n\nSou o assistente virtual e estou aqui para te ajudar com informações sobre nossos empreendimentos de alto padrão.\n\nComo posso te auxiliar?';
const abertura = hour < 12 ? 'Bom dia!' : hour < 18 ? 'Boa tarde!' : 'Boa noite!';
return [{ json: { to: from, session, responseText: `${abertura} ${corpo}` } }];

const qdrantResp = $input.first().json;
// Coleção inexistente ou Qdrant fora: continua como 'sem histórico'
const points = qdrantResp.error ? [] : (qdrantResp.result?.points || []);
const parsedData = $('Verificar Estado').first().json;
const currentMessage = parsedData.message;
const sorted = [...points].sort((a, b) => new Date(a.payload.timestamp) - new Date(b.payload.timestamp));
const historyLines = sorted.map(p => `Cliente: ${p.payload.pergunta_cliente || ''}\nAssistente: ${(p.payload.resposta_ia || '').slice(0, 200)}`).join('\n\n');
const hasHistory = historyLines.trim().length > 0;
return [{ json: { ...parsedData, hasHistory, historyLines, originalMessage: currentMessage } }];

const geminiResp = $input.first().json;
const contextData = $('Preparar Contexto Histórico').first().json;
// Se não passou pela reformulação (sem histórico) ou ela falhou, usa a pergunta original
const reformulada = (!geminiResp.error && geminiResp.candidates?.[0]?.content?.parts?.[0]?.text?.trim()) || contextData.originalMessage;
return [{ json: { ...contextData, message: reformulada, messageOriginal: contextData.originalMessage } }];

const qdrantResult = $input.first().json;
const apiFalhou = !!qdrantResult.error;
const results = apiFalhou ? [] : (qdrantResult.result || []);
const prevNode = $('Montar Query Enriquecida').first().json;
// Ajuste fino: se responder pouco, baixe; se responder coisa errada, suba.
const MIN_SCORE = 0.60;
const validResults = results.filter(r => r.score >= MIN_SCORE);
const hasContext = validResults.length > 0;
const topScore = results.length > 0 ? results[0].score : 0;
// O nó Qdrant do n8n (LangChain) grava o texto em payload.content
const contextText = validResults.map(r => `Documento: ${r.payload?.metadata?.source || 'Material LongView'}\nTrecho: ${r.payload?.content || r.payload?.text || r.payload?.pageContent || ''}\n(Relevância: ${(r.score * 100).toFixed(0)}%)`).join('\n\n---\n\n');
return [{ json: { ...prevNode, hasContext, contextText, topScore, shouldHandoff: !hasContext, handoffReason: apiFalhou ? 'erro_tecnico_api' : (!hasContext ? 'sem_contexto_suficiente' : null) } }];

// v11: número fixo aqui ($env costuma ser bloqueado no Code node)
const ATTENDANT_PHONE = '5548999999999'; // <<< TROQUE pelo número do atendente (só dígitos, com 55 + DDD)
const attendantChatId = ATTENDANT_PHONE.replace(/\D/g, '') + '@c.us';

const state = $('Verificar Estado').first().json;
const from = state.from;
const session = state.session;
const question = state.message;
const clientId = from.split('@')[0];
const isCritical = state.isCritical || false;

// No caminho 'assunto crítico' o RAG não roda, então esse nó pode não existir
let topScore = 0;
try { topScore = $('Validação de Confiança').first().json.topScore || 0; } catch (e) { topScore = 0; }

const inputData = $input.first().json;
const apiFalhou = !!inputData.error;
const handoffReason = isCritical
  ? 'assunto_critico'
  : (apiFalhou ? 'erro_tecnico_api' : (inputData.handoffReason || 'ia_rejeitou_contexto'));

const staticData = $getWorkflowStaticData('global');
if (!staticData.humanHandoff) staticData.humanHandoff = {};
const alreadyInHandoff = !!staticData.humanHandoff[from];
staticData.humanHandoff[from] = { since: new Date().toISOString(), reason: handoffReason };

const reasonLabel = {
  assunto_critico: '🔴 Assunto crítico (jurídico/rescisão/procon)',
  sem_contexto_suficiente: '🟡 Fora da base de conhecimento',
  sem_contexto: '🟡 Fora da base de conhecimento',
  ia_rejeitou_contexto: '🟠 IA julgou trecho insuficiente',
  erro_tecnico_api: '🔴 Falha técnica ao gerar resposta (API fora do ar/limite atingido)'
}[handoffReason] || '🟡 Motivo não identificado';

const attendantMsg = alreadyInHandoff
  ? `📩 *Nova mensagem — cliente em atendimento*\n\n*Cliente:* ${clientId}\n*Mensagem:* "${question}"`
  : `🔔 *Novo Transbordo — LongView*\n\n*Cliente:* ${clientId}\n*Última mensagem:* "${question}"\n*Motivo:* ${reasonLabel}\n*Score RAG:* ${(topScore * 100).toFixed(0)}%\n*Horário:* ${new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })}\n\nPara reativar a IA depois de atender, mande para este número:\n#bot ${clientId}`;

return [{ json: {
  from, session,
  clientMessage: alreadyInHandoff ? null : 'Compreendo perfeitamente. Estou transferindo você agora para um dos nossos especialistas LongView para garantir o melhor atendimento. Em breve entraremos em contato! 🏢',
  attendantMessage: attendantMsg, attendantPhone: attendantChatId, handoffReason, topScore, alreadyInHandoff
} }];

const transbordoData = $('Preparar Transbordo').first().json;
const stateNode = $('Verificar Estado').first().json;
const phone = transbordoData.from.split('@')[0];
const timestamp = new Date().toISOString();
const vector = Array(768).fill(0); vector[0] = 1;
const payload = { points: [{ id: Date.now(), vector, payload: { tipo: 'transbordo', telefone: phone, sessao: stateNode.session || 'default', pergunta_cliente: stateNode.message || '', resposta_ia: '[TRANSBORDO]', motivo_transbordo: transbordoData.handoffReason || 'desconhecido', score_relevancia: transbordoData.topScore || 0, timestamp, data_hora_br: new Date(timestamp).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) } }] };
return [{ json: { payload } }];

const geminiResponse = $('IA Reescreve (SEM criar)').first().json;
const stateNode = $('Verificar Estado').first().json;
const validacao = $('Validação de Confiança').first().json;
const rawText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
const fallback = 'Desculpe, ocorreu um erro ao processar sua mensagem. Um de nossos especialistas entrará em contato.';
let responseText;
try {
  const clean = rawText.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  responseText = JSON.parse(clean).texto || fallback;
} catch (e) {
  responseText = fallback;
}
return [{ json: { to: stateNode.from, phone: stateNode.phone, session: stateNode.session, responseText: responseText.trim(), originalMessage: stateNode.message, timestamp: stateNode.timestamp || new Date().toISOString(), topScore: validacao.topScore || 0, contextText: validacao.contextText || '' } }];

const data = $('Extrair Texto Formatado').first().json;
const phone = data.phone || String(data.to || '').split('@')[0] || 'desconhecido';
const timestamp = data.timestamp || new Date().toISOString();
const vector = Array(768).fill(0); vector[0] = 1;
const payload = { points: [{ id: Date.now(), vector, payload: { tipo: 'conversa_ia', telefone: phone, sessao: data.session || 'default', pergunta_cliente: data.originalMessage || '', resposta_ia: data.responseText || '', contexto_usado: data.contextText || '', score_relevancia: data.topScore || 0, timestamp, data_hora_br: new Date(timestamp).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) } }] };
return [{ json: { payload, phone, timestamp } }];

const binaryData = $input.first().binary;
const binaryKey = Object.keys(binaryData || {})[0] || 'file';
const fileName = binaryData?.[binaryKey]?.fileName || 'documento.pdf';
const fileNameClean = fileName.replace(/\.pdf$/i, '');
return [{ json: { source: fileNameClean, fileName, uploadedAt: new Date().toISOString() }, binary: binaryData }];

const binaryData = $input.first().binary;
const binaryKey = Object.keys(binaryData || {})[0] || 'file';
const fileName = binaryData?.[binaryKey]?.fileName || 'tabela.pdf';
const fileNameClean = fileName.replace(/\.(pdf|csv|txt)$/i, '');
const tipoDoc = $input.first().json['Tipo de documento'] || 'Documento';
return [{ json: { source: fileNameClean, fileName, tipoDoc, isStructured: true, uploadedAt: new Date().toISOString() }, binary: binaryData }];
